#!/bin/bash
#
# Create Survey Report Script using Antigravity CLI (agy).
#
# Environment variables used:
#   TARGET_URL: URL of the tool to survey and report (required)

set -euo pipefail

# Load common library
readonly SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
# shellcheck source=.github/workflows/scripts/agy-common.sh
source "${SCRIPT_DIR}/agy-common.sh"

#######################################
# Builds the prompt for creating a new report.
# Arguments:
#   target_url: Official or repository URL of the target tool
# Outputs:
#   Writes prompt string to stdout
#######################################
build_create_prompt() {
  local -r target_url="$1"
  local -r today_jst="$2"

  cat <<EOF
# 新規調査レポート作成指令

対象URL: ${target_url}

本日の日付（日本時間）: ${today_jst}

上記URL（公式サイトまたはGitHubリポジトリ）のツールについて、包括的な調査を行い新規調査レポートを作成せよ。

## 遵守すべき手順書・テンプレート
1. **基本作成手順**: \`task-report-create-or-update.md\` を参照し、「新規作成時の優先度」および全18セクション構成・形式・ガイドラインに厳密に従ってレポートを作成すること。
2. **テンプレート**: \`templates/template.md\` の構成を完全に再現して \`_reports/{tool-slug}.md\` を作成すること（ファイル名はツール名のケバブケース英小文字）。
3. **カテゴリ・タグ・関連付けの整理**: \`task-organizing-category-tags.md\` を参照し、標準語彙に従ってカテゴリ・タグを設定し、必要に応じて \`_data/categories.yml\` を更新すること。
4. **CodeWiki / DeepWikiリンクの規則**:
   - 推測によるURL記載は厳禁とする。実在確認が取れない場合はリンクを記載しないこと。
   - OSSリポジトリの場合は、\`pnpm run update-wiki _reports/{tool-slug}.md\` を実行して実在するWikiリンクのみを反映すること。
5. **動作原理・システム構成**:
   - 読者の理解を深めるため、日本語のMermaid図（フロー図や構成図）を可能な限り作成すること。
6. **代表的な利用フロー**:
   - Section 2 に「2.1 代表的な利用フロー」を設け、ユーザー・ツール・外部サービスなどのアクター別スイムレーンを \`swimlane-beta TB\` で作成すること（図内は日本語表記）。
   - Mermaidの \`subgraph\` 表示名に \`・\` や全角記号、\`(\` \`)\` などを含める場合は、必ず \`subgraph ID["表示名"]\` のように引用符で囲むこと。
7. **Mermaid静的検証**:
   - 作成後に \`uv run python3 scripts/check_mermaid.py --static _reports/{tool-slug}.md\` を実行し、Mermaidの構文エラーがないことを確認すること。
8. **ブラウザ検証（Playwright）のスキップ**:
   - 本環境（e2-micro）のリソース制約を考慮し、Playwrightなどのブラウザを起動する検証（\`--browser\`）は実行しないこと。

## 完了条件
- \`_reports/\` 配下に新規レポートファイルが生成されていること。
- フロントマターの \`date\` および \`last_updated\` は本日の日付（日本時間）\`${today_jst}\` に設定されていること。
- \`uv run python3 scripts/check_mermaid.py --static _reports/{tool-slug}.md\` が成功していること。
- \`_data/categories.yml\` の整合性が保たれていること。
- レポート作成後、ユーザーへの質問や確認（「提出してよいですか？」など）は一切行わず、自律的に作業を確定・完了させること。
EOF
}

#######################################
# Main execution function.
#######################################
main() {
  local -r target_url="${TARGET_URL:-}"

  if [[ -z "${target_url}" ]]; then
    log_error "TARGET_URL environment variable is required."
    exit 1
  fi

  log_info "Starting survey report creation for: ${target_url}"

  local -r today_jst="$(TZ='Asia/Tokyo' date +'%Y-%m-%d')"

  setup_git_and_gh

  local -r branch_name="create-report-${today_jst}-$(TZ='Asia/Tokyo' date +%H%M%S)"
  log_info "Creating and checking out branch: ${branch_name}"
  git checkout -b "${branch_name}"

  local prompt
  prompt="$(build_create_prompt "${target_url}" "${today_jst}")"

  if ! run_agy "${prompt}"; then
    log_error "Antigravity CLI execution failed."
    git checkout main
    git branch -D "${branch_name}" || true
    exit 1
  fi

  # Determine tool name from newly created report
  local new_report
  new_report="$(git status --porcelain "${REPORTS_DIR}" | grep -E '^(\?\?|A)[[:space:]]+_reports/' | awk '{print $NF}' | head -n 1 || true)"
  if [[ -z "${new_report}" ]]; then
    new_report="$(git status --porcelain "${REPORTS_DIR}" | awk '{print $NF}' | head -n 1 || true)"
  fi

  local tool_name="new tool"
  if [[ -n "${new_report}" ]] && [[ -f "${new_report}" ]]; then
    tool_name="$(extract_tool_name "${new_report}")"
  fi

  local -r commit_msg="feat: add survey report for ${tool_name}"
  local -r pr_title="feat: add survey report for ${tool_name}"
  local -r pr_body="Automated survey report generated by Antigravity CLI (agy) for ${target_url}"

  if ! commit_and_create_pr "${branch_name}" "${commit_msg}" "${pr_title}" "${pr_body}"; then
    log_error "Failed to commit or create pull request."
    git checkout main
    git branch -D "${branch_name}" || true
    exit 1
  fi

  git checkout main
  log_info "Survey report creation workflow completed successfully."
}

main "$@"

